    /**
     * Method to retrieve the Shipment via ShipmentFetchOneSummary
     * @param 	summary ShipmentFetchOneSummary 
     * @return 	ShipmentFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Shipment getShipment( ShipmentFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "ShipmentFetchOneSummary arg cannot be null" );
    	
    	Shipment entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Shipment
        	// --------------------------------------
        	CompletableFuture<Shipment> futureEntity = queryGateway.query(new FindShipmentQuery( new LoadShipmentFilter( summary.getShipmentId() ) ), ResponseTypes.instanceOf(Shipment.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Shipment with id " + summary.getShipmentId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


